def main():
    TEXT[84][0]='敌６名！'
    TEXT[102][1]='敌逃走！'
    TEXT[172][1]='确认破坏了脚。还剩３条！'
    target=ROOT/'translation/batches/417_rise_completion.generated.json';assert not target.exists()
    sources=defaultdict(list)
    for r in read(ROOT/'translation/catalog.working.json'):
        if r.get('translation') or not r['source'].startswith('export_base/battle/support/bsv105.'):continue
        m=int(re.search(r'_\((\d+)\)',r['source'])[1]);i=r['message_index'];j=r['line_index']
        if m<69 or 'ダミー' in r['original']:continue
        assert j==0
        body=(COUNT[i] if m==181 else TEXT[m][i])+'\n'
        a=TOKEN.sub('',r['original']).splitlines();b=body.splitlines()
        assert len(b)<=len(a) and max(map(len,b))<=max(map(len,a)),(m,i,a,b)
        s=r['source'];sources[s].append([i,j,read(ROOT/s)['texts'][i]['id'],body])
    total=sum(map(len,sources.values()));assert total==138,total
    write(target,dict(status='draft',sources=dict(sources),source_hashes={s:hashlib.sha256((ROOT/s).read_bytes()).hexdigest() for s in sources},review_notes=['理世069及以后剩余有效138页：分析、战败、Boss机制、倒计时；明确占位保持原样。','克洛诺斯及誓言术语沿用既有译法，保留数字；原文万能弱点照译，不等于验证存在可触发敌人。未运行验证。']))
    print('Rise completion pages:',total)

if __name__=='__main__':main()
